//! Cached observed changes and exact-ID read markers. No provider or filesystem reads.
use super::*;
use std::collections::BTreeSet;
const MAX_CHANGES:usize=500;
fn keys(args:&Value,allowed:&[&str])->Result<()>{let args=args.as_object().ok_or(Error::new("Change arguments must be an object."))?;if args.keys().any(|key|!allowed.contains(&key.as_str())){return Err(Error::new("Unknown change argument."));}Ok(())}
fn id(value:&Value)->Result<&str>{value.as_str().filter(|id|!id.trim().is_empty()&&id.chars().count()<=160&&!id.chars().any(char::is_control)).ok_or(Error::new("Supply a bounded observed change or work ID."))}
fn ids(value:&Value)->Result<Vec<String>>{let values=value.as_array().filter(|values|values.len()<=MAX_CHANGES).ok_or(Error::new("Supply at most 500 captured change IDs."))?;let mut seen=BTreeSet::new();let mut result=vec![];for value in values{let value=id(value)?.to_owned();if !seen.insert(value.clone()){return Err(Error::new("Captured change IDs must be unique."));}result.push(value);}Ok(result)}
fn rows(state:&Value)->Result<&Vec<Value>>{state["changes"].as_array().filter(|rows|rows.len()<=MAX_CHANGES).ok_or(Error::new("Cached changes exceed their supported limit."))}
fn prefix(repo:&Repository,value:&Value,bound:usize)->String{let mut value=value.as_str().unwrap_or("").to_owned();commands::redact_text(repo,&mut value);value.chars().take(bound).collect()}
fn projected_identity(repo:&Repository,value:&Value,optional:bool)->Result<String>{
    let identity=if optional&&(value.is_null()||value==""){""}else{id(value)?};let mut redacted=identity.to_owned();commands::redact_text(repo,&mut redacted);if redacted!=identity{return Err(Error::new("A cached change identity cannot be safely projected."));}Ok(identity.to_owned())
}
fn summary(repo:&Repository,row:&Value)->Result<Value>{
    let source=text(row,"source");if !["github","linear","sentry"].contains(&source){return Err(Error::new("A cached change has an unsupported source identity."));}
    let mut value=json!({"id":projected_identity(repo,&row["id"],false)?,"itemId":projected_identity(repo,&row["itemId"],true)?,"source":projected_identity(repo,&row["source"],false)?});
    for (field,bound) in [("title",300),("reference",160),("message",2000)]{value[field]=json!(prefix(repo,&row[field],bound));}
    value["url"]=json!(safe_url(&prefix(repo,&row["url"],4096)).unwrap_or_default());value["read"]=json!(row["read"]==true);value["at"]=row["at"].as_f64().filter(|time|time.is_finite()&&*time>=0.0).map_or(Value::Null,|time|json!(time));Ok(value)
}
pub fn list(repo:&Repository,args:&Value)->Result<Value>{
    keys(args,&["limit","afterId","source","unread","itemId"])?;
    let limit=match args.get("limit"){Some(value)=>value.as_u64().filter(|value|(1..=100).contains(value)).ok_or(Error::new("Choose a change limit from 1 to 100."))? as usize,None=>40};
    let after=args.get("afterId").map(id).transpose()?;let item=args.get("itemId").map(id).transpose()?;
    let source=match args.get("source"){Some(value)=>Some(value.as_str().filter(|value|["github","linear","sentry"].contains(value)).ok_or(Error::new("Choose a supported change source."))?),None=>None};
    let unread=args.get("unread").map(|value|value.as_bool().ok_or(Error::new("Unread must be a boolean."))).transpose()?;
    let snapshot={let state=repo.state.lock().map_err(|_|Error::io())?;rows(&state)?.clone()};
    let start=match after{Some(after)=>snapshot.iter().position(|row|row["id"]==after).map(|index|index+1).ok_or_else(||{let mut error=Error::new("The change cursor was pruned. Restart changes.list without afterId.");error.status=409;error})?,None=>0};
    let matches=|row:&&Value|source.is_none_or(|source|row["source"]==source)&&item.is_none_or(|item|row["itemId"]==item)&&unread.is_none_or(|unread|(row["read"]!=true)==unread);
    let total=snapshot.iter().filter(matches).count();let matching=snapshot.iter().skip(start).filter(matches).collect::<Vec<_>>();let has_more=matching.len()>limit;let page=matching.into_iter().take(limit).map(|row|summary(repo,row)).collect::<Result<Vec<_>>>()?;
    let next=if has_more{page.last().map(|row|row["id"].clone()).unwrap_or(Value::Null)}else{Value::Null};
    Ok(json!({"changes":page,"total":total,"nextAfterId":next,"scope":"cached"}))
}
pub(super) fn mark_in_state(state:&mut Value,args:&Value)->Result<Value>{
    keys(args,&["ids"])?;let requested=ids(&args["ids"])?;rows(state)?;let mut marked=vec![];let mut already=vec![];let mut absent=vec![];
    for id in &requested{match state["changes"].as_array_mut().unwrap().iter_mut().find(|row|row["id"]==*id){Some(row)=>{if row["read"]==true{already.push(id.clone());}else{row["read"]=json!(true);marked.push(id.clone());}},None=>absent.push(id.clone())}}
    Ok(json!({"requestedIds":requested,"markedCount":marked.len(),"markedIds":marked,"alreadyReadIds":already,"absentIds":absent,"scope":"local"}))
}
pub fn mark_read(repo:&Repository,args:&Value)->Result<Value>{keys(args,&["ids"])?;for value in ids(&args["ids"])?{projected_identity(repo,&json!(value),false)?;}repo.transaction_if_changed(|state|mark_in_state(state,args))}
pub(super) fn legacy_mark(state:&mut Value,args:&Value)->Result<Value>{
    if args.get("all").is_some(){return Err(Error::new("Global mark-all is retired. Supply the captured change IDs instead."));}
    keys(args,&["action","id","ids"])?;if args.get("id").is_some()&&args.get("ids").is_some(){return Err(Error::new("Supply captured IDs or one ID, not both."));}
    let captured=if let Some(value)=args.get("id"){json!({"ids":[id(value)?]})}else{json!({"ids":args["ids"]})};mark_in_state(state,&captured)
}
#[cfg(test)]
mod tests{
 use super::*;use std::sync::Arc;
 fn fixture()->(tempfile::TempDir,Arc<Repository>){let temp=tempfile::tempdir().unwrap();let repo=Repository::open(temp.path().into(),None,true).unwrap();repo.transaction(|state|{state["changes"]=json!([{"id":"a","itemId":"work:a","title":"Title","source":"github","message":"Ready","read":false,"privateNs":{"secret":"do-not-project"}},{"id":"b","itemId":"work:b","source":"linear","read":true},{"id":"c","itemId":"work:a","source":"github","read":false}]);Ok(())}).unwrap();(temp,repo)}
 #[test]fn changes_list_is_bounded_read_only_whitelisted_and_stable_under_arrivals(){let (_temp,repo)=fixture();let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();let first=list(&repo,&json!({"limit":1,"unread":true})).unwrap();assert_eq!(first["changes"][0]["id"],"a");assert_eq!(first["nextAfterId"],"a");assert!(!first.to_string().contains("do-not-project"));assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);repo.transaction(|state|{state["changes"].as_array_mut().unwrap().insert(0,json!({"id":"new","source":"github","read":false}));Ok(())}).unwrap();let second=list(&repo,&json!({"afterId":"a","unread":true,"source":"github","itemId":"work:a"})).unwrap();assert_eq!(second["changes"].as_array().unwrap().len(),1);assert_eq!(second["changes"][0]["id"],"c");assert_eq!(second["nextAfterId"],Value::Null);assert_eq!(list(&repo,&json!({"afterId":"pruned"})).unwrap_err().status,409);assert!(repo.embedded.inventory().is_empty());assert!(repo.cooldown.lock().unwrap().is_empty());}
 #[test]fn changes_mark_exact_ids_preserves_late_arrivals_extensions_and_reports_pruned(){let (_temp,repo)=fixture();let captured=json!({"ids":["a","b","pruned"]});repo.transaction(|state|{state["changes"].as_array_mut().unwrap().insert(0,json!({"id":"late","read":false,"extension":17}));Ok(())}).unwrap();let result=mark_read(&repo,&captured).unwrap();assert_eq!(result,json!({"requestedIds":["a","b","pruned"],"markedIds":["a"],"alreadyReadIds":["b"],"absentIds":["pruned"],"markedCount":1,"scope":"local"}));let state=repo.state.lock().unwrap().clone();assert_eq!(state["changes"][0],json!({"id":"late","read":false,"extension":17}));assert_eq!(state["changes"][1]["privateNs"]["secret"],"do-not-project");assert_eq!(state["changes"][3]["read"],false);assert_eq!(serde_json::from_slice::<Value>(&std::fs::read(&repo.data).unwrap()).unwrap()["changes"],state["changes"]);let before=std::fs::read(&repo.data).unwrap();assert_eq!(mark_read(&repo,&captured).unwrap()["markedCount"],0);assert_eq!(std::fs::read(&repo.data).unwrap(),before);}
 #[test]fn changes_invalid_and_legacy_global_arguments_fail_before_effects(){let (_temp,repo)=fixture();let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();for args in [json!({}),json!({"ids":["a","a"]}),json!({"ids":[""]}),json!({"ids":[7]}),json!({"ids":vec!["a";501]}),json!({"ids":["a"],"all":true})]{assert!(mark_read(&repo,&args).is_err());}for args in [json!({"limit":0}),json!({"limit":101}),json!({"unread":7}),json!({"source":"other"}),json!({"offset":1})]{assert!(list(&repo,&args).is_err());}for args in [json!({"action":"read-changes","all":true}),json!({"action":"read-changes","all":false,"id":"a"}),json!({"action":"read-changes","id":"a","ids":["a"]})]{assert!(repo.transaction(|state|domain::edit(state,&args)).is_err());}assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);repo.transaction(|state|domain::edit(state,&json!({"action":"read-changes","id":"a"}))).unwrap();assert_eq!(repo.state.lock().unwrap()["changes"][0]["read"],true);assert_eq!(repo.state.lock().unwrap()["changes"][2]["read"],false);}
 #[test]fn changes_redact_before_display_limits_and_reject_unsafe_urls(){let temp=tempfile::tempdir().unwrap();let secret=format!("private-change-{}","X".repeat(350));std::fs::write(temp.path().join(".env"),format!("MYDASH_TEST_SECRET={secret}\n")).unwrap();let repo=Repository::open(temp.path().into(),None,true).unwrap();repo.transaction(|state|{state["changes"]=json!([{"id":"a","title":format!("{secret} {}","界".repeat(400)),"message":secret,"source":"github","url":"https://user:password@example.invalid/private","at":-2,"privateExtension":"hidden-projection"}]);Ok(())}).unwrap();let result=list(&repo,&json!({})).unwrap();assert!(text(&result["changes"][0],"title").starts_with("[redacted] "));assert_eq!(text(&result["changes"][0],"title").chars().count(),300);assert_eq!(result["changes"][0]["message"],"[redacted]");assert_eq!(result["changes"][0]["url"],"");assert_eq!(result["changes"][0]["at"],Value::Null);assert!(!result.to_string().contains("hidden-projection"));}
 #[test]fn changes_failed_save_preserves_memory_and_canonical_bytes_then_allows_exact_retry(){let (_temp,repo)=fixture();let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();std::fs::create_dir(repo.data.with_extension("tmp")).unwrap();assert!(mark_read(&repo,&json!({"ids":["a"]})).is_err());assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);std::fs::remove_dir(repo.data.with_extension("tmp")).unwrap();assert_eq!(mark_read(&repo,&json!({"ids":["a"]})).unwrap()["markedIds"],json!(["a"]));}

 #[test]fn changes_identity_projection_is_exact_or_fails_without_exposing_or_marking_secrets(){
  let temp=tempfile::tempdir().unwrap();let secret="private-cursor-identity";std::fs::write(temp.path().join(".env"),format!("MYDASH_TEST_SECRET={secret}\n")).unwrap();let repo=Repository::open(temp.path().into(),None,true).unwrap();
  for (field,value) in [("id",json!(secret)),("id",json!("x".repeat(161))),("id",json!("unsafe\nidentity")),("itemId",json!(secret)),("itemId",json!("x".repeat(161))),("itemId",json!("unsafe\tidentity")),("source",json!("unknown-source"))]{repo.transaction(|state|{state["changes"]=json!([{"id":"safe-id","itemId":"safe-work","source":"github","read":false},{"id":"next","source":"linear","read":false}]);state["changes"][0][field]=value.clone();Ok(())}).unwrap();let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();let error=commands::invoke(&repo,&json!({"name":"changes.list","args":{"limit":1}}),true).unwrap_err();assert!(!error.message.contains(secret));assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);}
  for present in [false,true]{repo.transaction(|state|{state["changes"]=json!([{"id":if present{secret}else{"safe-id"},"source":"github","read":false},{"id":"next","source":"linear","read":false}]);Ok(())}).unwrap();let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();assert!(commands::invoke(&repo,&json!({"name":"changes.mark-read","args":{"ids":["next",secret]}}),true).is_err());assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);}
  repo.transaction(|state|{state["changes"]=json!([{"id":"safe-id","source":"github"},{"id":"next","source":"linear"}]);Ok(())}).unwrap();let result=commands::invoke(&repo,&json!({"name":"changes.list","args":{"limit":1}}),true).unwrap();assert_eq!(result["changes"][0]["id"],"safe-id");assert_eq!(result["changes"][0]["itemId"],"");assert_eq!(result["nextAfterId"],"safe-id");
 }

}
